            aWandererB = aWandererB ^ ((RotL64(aPrevious, 6U) + aOrbiterF) + RotL64(aOrbiterC, 57U));
            aWandererI = aWandererI + ((RotL64(aCross, 21U) + aOrbiterC) + RotL64(aOrbiterG, 13U));
