            //
            aIngress = (RotL64(aKineticLaneC[((aIndex + 29834U)) & S_BLOCK1], 5U) ^ RotL64(aKineticLaneA[((aIndex + 28899U)) & S_BLOCK1], 13U));
            aIngress ^= RotL64(aMagmaLaneA[((S_BLOCK1 - aIndex + 29201U)) & S_BLOCK1], 27U);
