            aOrbiterG = ((aWandererJ + RotL64(aPrevious, 19U)) + 0x4ADA8EC1065F1214ULL) + aNonceWordG;
            aOrbiterD = ((aWandererB + RotL64(aCross, 39U)) + RotL64(aCarry, 47U)) + 0x22D5E2D0E1B11721ULL;
            aOrbiterB = ((aWandererH + RotL64(aIngress, 30U)) + 0x1D4C550DB41D0716ULL) + aNonceWordE;
            aOrbiterE = ((aWandererC + RotL64(aScatter, 21U)) + 0xA8102689E1562219ULL) + aOASaltH[(((511U - aIndex) + 167U)) & S_SALT1];
            aOrbiterK = ((aWandererI + RotL64(aPrevious, 3U)) + 0xB2E0857EF5A8083FULL) + aOASaltE[((aIndex + 385U)) & S_SALT1];
            aOrbiterA = ((aWandererA + RotL64(aCross, 51U)) + RotL64(aCarry, 3U)) + 0xB9A1AD88B810844FULL;
            aOrbiterJ = ((aWandererD + RotL64(aIngress, 37U)) + 0xC2AA40D35B5E58D2ULL) + aNonceWordO;
            aOrbiterC = (((aWandererK + RotL64(aScatter, 54U)) + 0x1D1FCF26A4A9127DULL) + aOASaltC[((aIndex + 498U)) & S_SALT1]) + aNonceWordP;
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0xF604C5069F49F6D1ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xCAAEBAC54158B2D0ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x50CD2B65F36A9A45ULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0xF1BD66D0560BC17DULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterG) ^ 0x2EF6079876430E2DULL) ^ aNonceWordB;
            aOrbiterB = RotL64((aOrbiterB * 0xF434082CF7999863ULL), 53U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0xC8F19B7677D8F1F4ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x0506B51B1D9D6134ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x9E58F8130F0A1BB3ULL), 57U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0x6B42E0E2B0DC5BC4ULL) + aOUSaltE[(((511U - aIndex) + 401U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x8C1C727DEDEFC041ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x4D9390EB099A1CBDULL), 37U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterK) + 0x29CC1F735A93BF43ULL) + aOUSaltH[(((511U - aIndex) + 277U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0xC154AC0F5785969BULL;
            aOrbiterI = RotL64((aOrbiterI * 0x34BE45A99A966FC3ULL), 19U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x6E32C52EBB6020C9ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x33327B44062F27C1ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xDD58F2F1E2EC92F1ULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x796D825AE471E506ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterI) ^ 0x56EB80EDE48DCD02ULL) ^ aOUSaltB[(((511U - aIndex) + 226U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xCC519CD6FDB9E7D1ULL), 23U);
            //
            aOrbiterD = (((aOrbiterD + aOrbiterE) + 0xB17F51C7C8958B94ULL) + aOUSaltC[(((511U - aIndex) + 353U)) & S_SALT1]) + aNonceWordJ;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x6251B5B4754EDE47ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xBEA38160328C11DDULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0xD3A73112CB466E41ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0x375F09F376FB4D3BULL) ^ aOUSaltG[((aIndex + 397U)) & S_SALT1];
