            aWandererI = aWandererI + (((RotL64(aPrevious, 54U) + RotL64(aOrbiterB, 57U)) + aOrbiterE) + aWUSaltA[(((511U - aIndex) + 470U)) & S_SALT1]);
            aWandererF = aWandererF ^ ((RotL64(aCross, 13U) + aOrbiterH) + RotL64(aOrbiterK, 41U));
            aWandererD = aWandererD + ((RotL64(aIngress, 41U) + RotL64(aOrbiterC, 12U)) + aOrbiterF);
            aWandererB = aWandererB ^ ((((RotL64(aScatter, 23U) + RotL64(aOrbiterE, 35U)) + aOrbiterA) + RotL64(aCarry, 11U)) + aNonceWordL);
            aWandererH = aWandererH + (((RotL64(aPrevious, 10U) + aOrbiterF) + RotL64(aOrbiterG, 21U)) + aWUSaltE[(((511U - aIndex) + 133U)) & S_SALT1]);
            aWandererA = aWandererA ^ ((RotL64(aCross, 39U) + RotL64(aOrbiterJ, 29U)) + aOrbiterI);
            aWandererE = aWandererE + (((RotL64(aIngress, 21U) + RotL64(aOrbiterG, 51U)) + aOrbiterJ) + aWUSaltB[((aIndex + 274U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 47U) + aOrbiterD) + RotL64(aOrbiterC, 23U));
