            aWandererA = aWandererA ^ (((RotL64(aScatter, 43U) + aOrbiterC) + RotL64(aOrbiterG, 56U)) + aWUSaltB[((aIndex + 322U)) & S_SALT1]);
            aWandererB = aWandererB + ((((RotL64(aPrevious, 60U) + RotL64(aOrbiterG, 3U)) + aOrbiterH) + RotL64(aCarry, 5U)) + aWUSaltF[((aIndex + 109U)) & S_SALT1]);
            //
