            aOrbiterC = (aWandererI + RotL64(aScatter, 47U)) + 0xCC58D263C27A7F66ULL;
            aOrbiterK = ((aWandererG + RotL64(aPrevious, 19U)) + RotL64(aCarry, 5U)) + 0x8FC4299E5F94176CULL;
