            aOrbiterI = ((aWandererD + RotL64(aScatter, 39U)) + 0x4098A7626C2ED2F0ULL) + aOASaltC[(((511U - aIndex) + 177U)) & S_SALT1];
            aOrbiterE = (aWandererH + RotL64(aPrevious, 19U)) + 0xCD63CAAEF0971BE9ULL;
