            aOrbiterD = RotL64((aOrbiterD * 0x1C6D9D75D04C5409ULL), 37U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x62C6CEF49B6CED76ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterH) ^ 0xB53178F606ECAB0BULL) ^ aOUSaltF[(((511U - aIndex) + 240U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xB5ECDA032EF6DEA1ULL), 19U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0x1BB72F9E4C2A0B05ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0x61585F9A3E9FABDAULL) ^ aOUSaltC[((aIndex + 121U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xCC9A8FB9A76346E3ULL), 53U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterD) + 0x13CD6D0FC3F29248ULL) + aOUSaltB[((aIndex + 143U)) & S_SALT1];
